import {Request, Response} from "express";
import CarModel, {ICarModel} from '../models/car.model'
import * as mongoose from 'mongoose';
import {ObjectID} from "bson";
import {PaginateOptions, PaginateResult} from "mongoose";
import {IRequest} from "../../interfaces/global.interface";
import ParticipantModel from "../../form/models/participant.model";

class CarController {

  constructor() {
    this.generalDashboard = this.generalDashboard.bind(this);
    this.vinDashboard = this.vinDashboard.bind(this);
    this.vinDashboardDetail = this.vinDashboardDetail.bind(this);
    this.checkVIN = this.checkVIN.bind(this);
    this.apiCars = this.apiCars.bind(this);
    this.apiCarDetail = this.apiCarDetail.bind(this);
    this.getCars = this.getCars.bind(this);
    this.apiParticipantDetail = this.apiParticipantDetail.bind(this);
    this.apiParticipantsPerDate = this.apiParticipantsPerDate.bind(this);
  }

  public generalDashboard(req: Request, res: Response) {
    res.render('app/index');
  }

  public vinDashboard(req: Request, res: Response) {
    res.render('app/index');
  }

  public async checkVIN(req: IRequest, res: Response) {
    let {vin, vin2} = req.body;
    const company = req.user.company;

    const carBrands: any = {
      'VF1': 'RENAULT',
      'VF2': 'RENAULT',
      'VF6': 'RENAULT',
      '8A1': 'RENAULT',
      '93Y': 'RENAULT',
      '9FB': 'RENAULT',
      '3BR': 'RENAULT',
      'JC1': 'MAZDA',
      'JMZ': 'MAZDA',
      'JM6': 'MAZDA',
      'JM7': 'MAZDA',
      'PE3': 'MAZDA',
      'MM8': 'MAZDA',
      'MM0': 'MAZDA',
      'MM7': 'MAZDA',
      '1YV': 'MAZDA',
      '3MD': 'MAZDA',
      'JS2': 'SUZUKI',
      'MMS': 'SUZUKI',
      'JS3': 'SUZUKI',
      'IJS': 'SUZUKI',
      'TSM': 'SUZUKI',
      'MA3': 'SUZUKI',
      'MHY': 'SUZUKI',
      'LJ1': 'JAC',
      'LS4': 'CHANGAN',
      'LSC': 'CHANGAN',
      'LS5': 'CHANGAN',
      'LPA': 'CHANGAN',
      'LVR': 'CHANGAN',
      'LVS': 'CHANGAN',
      'LGW': 'GREAT WALL'
    };

    /*
    {
      $group: {
        _id: {
          vin: {
            $substr: ["$vin", 0, 3]
          },
          brand: "$brand"
        }
      }
    }
    */

    if (vin) {
      vin = vin.replace(/[\W_]+/g,"");
      try {
        const indexBrand: string = vin.slice(0, 3);
        vin2 = vin.substr(vin.length - 6);
        const brand = carBrands.hasOwnProperty(indexBrand) ? carBrands[indexBrand] : null;
        const car = await CarModel.findOneOrCreate({
          vin,
          company
        }, {
          vin,
          vin2,
          company,
          brand
        });
        res.json({
          data: {
            _id: car._id,
            vin: car.vin,
            vin2: car.vin2,
            brand: car.brand,
            color: car.color,
            denomination: car.denomination,
          },
          status: 200
        })
      } catch (e) {
        if (e) res.status(500).send(e);
      }
    } else if (vin2) {
      vin2 = vin2.replace(/[\W_]+/g,"");
      try {
        const car = await CarModel.findOne({
          vin2,
          company
        }, {
          vin: true,
          vin2: true,
          brand: true,
          color: true,
          denomination: true
        });
        if (car) {
          res.json({
            data: {
              _id: car._id,
              vin: car.vin,
              vin2: car.vin2,
              brand: car.brand,
              color: car.color,
              denomination: car.denomination,
            },
            status: 200
          })
        } else {
          res.status(400).json({
            message: 'VIN no encontrado.',
            status: 400
          })
        }
      } catch (e) {
        if (e) res.status(500).send(e);
      }
    } else {
      res.status(400).json({
        message: 'VIN no encontrado.',
        status: 400
      })
    }
  }

  public async vinDashboardDetail(req: IRequest, res: Response) {
    const {id} = req.params;
    const company = req.user.company;
    // validate params
    if (!mongoose.Types.ObjectId.isValid(id)) {
      return res.status(404).render('404');
    }
    try {
      // validate car exist
      const car = await CarModel.findOne({
        _id: id, company
      });
      if (!car) {
        return res.status(404).render('404');
      } else {
        res.render('app/index');
      }
    } catch (e) {
      if (e) res.status(500).send(e);
    }
  }

  public async apiParticipantsPerDate(req: IRequest, res: Response) {
    const company = req.user.company;
    try {
      const participantPerDay = await ParticipantModel
        .aggregate([{
          $match: {
            company
          }
        }, {
          $group: {
            // _id: {
            //   $dateToString: {
            //     format: '%Y-%m-%d',
            //     date: '$createdAt'
            //   },
            // },
            _id: {
              category: {
                $dateToString: {
                  format: '%Y-%m-%d',
                  date: '$createdAt'
                },
              },
              user: "$user",
            },
            total: {
              $sum: 1
            }
          }
        }, {
          $lookup: {
            from: "users",
            localField: "_id.user",
            foreignField: "_id",
            as: "userInfo",
          }
        }, {
          $unwind: "$userInfo"
        }, {
          $project: {
            '_id.category': 1,
            '_id.user': 1,
            'total': 1,
            'userInfo._id': 1,
            'userInfo.firstName': 1,
            'userInfo.lastName': 1,
          }
        }, {
          $group: {
            _id: "$_id.category",
            users: {
              $push: {
                user: "$_id.user",
                userInfo: "$userInfo",
                total: "$total"
              }
            },
            total: {$sum: "$total"}
          }
        }, {
          $sort: {
            _id: 1
          }
        }]);
      res.json({
          data: participantPerDay,
          status: 200
        });
    } catch (e) {
      if (e) res.status(500).json(e);
    }
  }

  public async apiParticipantDetail(req: IRequest, res: Response) {
    const {id} = req.params;
    const company = req.user.company;
    try {
      const participant = await ParticipantModel
        .findOne({
          _id: id, company
        }, {
          name: true,
          user: true,
          sections: true,
          qualification: true,
          createdAt: true
        })
        .populate([{
          path: 'user',
          select: ['firstName', 'lastName']
        }]);
      // validate exist participant
      if (!participant) {
        res.status(404).json({
          messsage: 'Formulario no encontrado.',
          status: 404
        });
      } else {
        res.json({
          data: participant,
          status: 200
        });
      }
    } catch (e) {
      if (e) res.status(500).json(e);
    }
  }

  public async apiCarDetail(req: IRequest, res: Response) {
    const company = req.user.company;
    const {id} = req.params;
    try {
      const car = await CarModel
        .findOne({
          _id: id,
          company
        }, {
          vin: true,
          brand: true,
          denomination: true,
          color: true
        })
        .populate([{
          // reverse populate
          path: 'participants',
          select: ['name', 'user', 'createdAt', 'qualification'],
          options:{
            sort: {
              createdAt: -1
            }
          },
          // deep populate user
          populate: [{
            path: 'user',
            select: ['firstName', 'lastName']
          }]
        }]).lean();
      if (!car) {
        res.status(404).json({
          messsage: 'Auto no encontrado.',
          status: 404
        });
      } else {
        res.json({
          data: car,
          status: 200
        });
      }
    } catch (e) {
      if (e) res.status(500).json(e);
    }
  }

  public async apiCars(req: IRequest, res: Response) {
    const company = req.user.company;
    const {page, pageSize} = req.query;

    // paginate options
    const options: PaginateOptions = {
      select: {
        vin: true,
        brand: true,
        denomination: true,
        color: true
      },
      populate: [{
        path: 'lastForm',
        select: ['createdAt', 'user', 'qualification'],
        populate: [{
          path: 'user',
          select: ['firstName', 'lastName']
        }]
      }],
      sort: {
        updatedAt: -1
      },
      page: parseInt(page ? page : 1),
      limit: parseInt(pageSize ? pageSize : 20),
    };
    try {
      const cars = await this.getCars(company, options);

      // validate exist page
      if (options.page && cars.pages && cars.pages < options.page) {
        res.status(400).json({
          message: 'La página solicitada no existe.',
          status: 200,
        });
      } else {
        res.json({
          count: cars.total,
          pages: cars.pages,
          hasPrevious: options.page && options.page > 1 && cars.pages && cars.pages >= options.page,
          hasNext: options.page && cars.pages && cars.pages > options.page,
          results: cars.docs,
          status: 200,
        });
      }
    } catch (e) {
      if (e) res.status(500).json(e);
    }
  }

  private getCars(company: ObjectID, options: PaginateOptions): Promise<PaginateResult<ICarModel>> {
    return new Promise((resolve, reject) => {
      CarModel.paginate({company, lastForm: {$exists: true, $ne: null}}, options, (err, result) => {
        if (err) {
          return reject(err);
        }
        return resolve(result);
      });
    });
  }
}

export default new CarController();
